begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values
 ('f0000000-0000-4000-8000-000000002620','privacy-owner@example.test',now()),
 ('f0000000-0000-4000-8000-000000002621','privacy-seller@example.test',now()),
 ('f0000000-0000-4000-8000-000000002622','privacy-staff@example.test',now());
set local role authenticated;
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000002620","role":"authenticated"}';
select set_config('test.tenant',create_tenant('Privacy test','privacy-test',gen_random_uuid())::text,true);
select set_config('test.other',create_tenant('Other privacy test','privacy-other-test',gen_random_uuid())::text,true);
select set_config('test.seller',register_seller(current_setting('test.tenant')::uuid,gen_random_uuid(),'Privacy Seller','privacy-seller@example.test','')::text,true);
select set_config('test.otherSeller',register_seller(current_setting('test.other')::uuid,gen_random_uuid(),'Same account','privacy-seller@example.test','')::text,true);
select set_config('test.profile','{"name":"Edited Seller","email":"privacy-seller@example.test","phone":"12345","addressLine1":"Private address","addressLine2":"","postalCode":"12345","city":"Test","country":"","language":"en","notes":"Private note"}',true);
select save_seller_profile(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,0,current_setting('test.profile')::jsonb);
select set_config('test.session',create_reception_session(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid)::text,true);
select set_config('test.terms',publish_seller_agreement(current_setting('test.tenant')::uuid,gen_random_uuid(),null,'TEST','Synthetic terms','en',false)::text,true);
select record_agreement_evidence(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,current_setting('test.terms')::uuid,'Synthetic paper approval');
select save_reception_sources(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.session')::uuid,0,'[{"id":"d0000000-0000-4000-8000-000000000010","kind":"price-evidence","reference":"TEST","observation":"Synthetic 80 SEK"}]'::jsonb);
select set_config('test.review',gen_random_uuid()::text,true);
select publish_reception_review(current_setting('test.tenant')::uuid,current_setting('test.review')::uuid,current_setting('test.session')::uuid,1,null,current_setting('test.terms')::uuid,'{"attributes":[{"slug":"description","definitionVersion":1,"value":"TEST shirt","sourceIds":["d0000000-0000-4000-8000-000000000010"],"certainty":"observed"}],"price":{"currency":"SEK","amount":"80.00","rationale":"TEST","sourceIds":["d0000000-0000-4000-8000-000000000010"]},"questions":[]}'::jsonb,now()+interval '1 day');
select set_reception_access(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.review')::uuid,null,encode(sha256(convert_to(repeat('e',64),'UTF8')),'hex'));
select set_config('test.preview',seller_privacy_preview(current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid)::text,true);
select is((current_setting('test.preview')::jsonb->>'canErase')::boolean,true,'empty seller can close');
select throws_like($$select seller_privacy_preview(current_setting('test.other')::uuid,current_setting('test.seller')::uuid)$$,'%SELLER_NOT_FOUND%','cross-tenant lookup refused');
select set_config('test.id',gen_random_uuid()::text,true);
select set_config('test.statement',issue_statement(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,'2020-01-01','2020-02-01',null)::text,true);
select set_config('test.preview',seller_privacy_preview(current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid)::text,true);
select set_config('test.message',queue_seller_communication(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,'message','privacy.test','v1','en','Private subject','Private body','none',null)::text,true);
select is((seller_privacy_preview(current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid)->>'canErase')::boolean,false,'queued mail blocks erasure');
select throws_like($$select erase_seller_contact(current_setting('test.tenant')::uuid,current_setting('test.id')::uuid,current_setting('test.seller')::uuid,current_setting('test.preview')::jsonb->>'revision','Reviewed legal evidence',current_date+30,true)$$,'%PRIVACY_CHANGED%','new outgoing message invalidates preview');
reset role;
select set_config('komisio.communication_delivery','engine',true);
update seller_communications set status='sent',delivered_at=now() where id=current_setting('test.message')::uuid;
select set_config('komisio.communication_delivery','',true);
set local role authenticated;
select set_config('test.preview',seller_privacy_preview(current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid)::text,true);
select throws_like($$select erase_seller_contact(current_setting('test.tenant')::uuid,current_setting('test.id')::uuid,current_setting('test.seller')::uuid,'stale','Reviewed legal evidence',current_date+30,true)$$,'%PRIVACY_CHANGED%','stale preview refused');
select throws_like($$select erase_seller_contact(current_setting('test.tenant')::uuid,current_setting('test.id')::uuid,current_setting('test.seller')::uuid,current_setting('test.preview')::jsonb->>'revision','Reviewed legal evidence',current_date+30,false)$$,'%INVALID_INPUT%','explicit confirmation required');
select throws_like($$select erase_seller_contact(current_setting('test.tenant')::uuid,current_setting('test.id')::uuid,current_setting('test.seller')::uuid,current_setting('test.preview')::jsonb->>'revision','Reviewed legal evidence',current_date-1,true)$$,'%INVALID_INPUT%','past review date refused');
select is((select count(*)::int from seller_privacy_events),0,'failed requests leave no erasure event');
select lives_ok($$select erase_seller_contact(current_setting('test.tenant')::uuid,current_setting('test.id')::uuid,current_setting('test.seller')::uuid,current_setting('test.preview')::jsonb->>'revision','Reviewed legal evidence',current_date+30,true)$$,'reviewed contact erasure succeeds');
select is((select email from sellers where id=current_setting('test.seller')::uuid),'','email erased');
select is((select phone from sellers where id=current_setting('test.seller')::uuid),'','phone erased');
select ok((select profile is null from sellers where id=current_setting('test.seller')::uuid),'profile erased');
select is((select subject from seller_communications where id=current_setting('test.message')::uuid),'Removed','ordinary message content redacted');
select is((select recipient from seller_communications where id=current_setting('test.message')::uuid),'redacted','ordinary message recipient redacted');
select is((select seller_email from reception_reviews where id=current_setting('test.review')::uuid),'','review contact copy erased');
select is((select count(*)::int from reception_reviews where id=current_setting('test.review')::uuid),1,'review evidence preserved');
select is((select seller_contact->>'name' from settlement_statements where id=current_setting('test.statement')::uuid),'Edited Seller','required statement contact stays intact');
select is((select count(*)::int from seller_profile_versions where seller_id=current_setting('test.seller')::uuid),0,'old contact copies erased');
select is((select email from sellers where id=current_setting('test.otherSeller')::uuid),'privacy-seller@example.test','other store untouched');
select lives_ok($$select erase_seller_contact(current_setting('test.tenant')::uuid,current_setting('test.id')::uuid,current_setting('test.seller')::uuid,current_setting('test.preview')::jsonb->>'revision','Reviewed legal evidence',current_date+30,true)$$,'exact retry succeeds');
select throws_like($$select erase_seller_contact(current_setting('test.tenant')::uuid,current_setting('test.id')::uuid,current_setting('test.seller')::uuid,current_setting('test.preview')::jsonb->>'revision','Changed reason',current_date+30,true)$$,'%REQUEST_CONFLICT%','retry cannot change decision');
select throws_like($$select save_seller_profile(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,1,current_setting('test.profile')::jsonb)$$,'%SELLER_CLOSED%','stale editor cannot restore erased data');
select throws_like($$select receive_bag_with_agreement(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,'',current_setting('test.terms')::uuid)$$,'%SELLER_CLOSED%','closed seller cannot receive new goods');
select lives_ok($$select review_seller_retention(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,seller_privacy_preview(current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid)->>'revision','Accounting evidence still required',current_date+60,true)$$,'retention follow-up is a new event');
select is((select count(*)::int from seller_privacy_events where seller_id=current_setting('test.seller')::uuid),2,'retention follow-up preserves original decision');
select set_config('test.blocked',register_seller(current_setting('test.tenant')::uuid,gen_random_uuid(),'Blocked seller','blocked@example.test','')::text,true);
select record_agreement_evidence(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.blocked')::uuid,current_setting('test.terms')::uuid,'Synthetic paper approval');
select adjust_seller_ledger(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.blocked')::uuid,-100,'Synthetic test debit');
select set_config('test.blockedPreview',seller_privacy_preview(current_setting('test.tenant')::uuid,current_setting('test.blocked')::uuid)::text,true);
select is((current_setting('test.blockedPreview')::jsonb#>>'{blockers,balance}')::boolean,true,'negative balance also blocks');
select throws_like($$select erase_seller_contact(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.blocked')::uuid,current_setting('test.blockedPreview')::jsonb->>'revision','Reviewed legal evidence',current_date+30,true)$$,'%PRIVACY_BLOCKED%','balance prevents erasure at engine boundary');
select adjust_seller_ledger(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.blocked')::uuid,100,'Synthetic correction');
select receive_bag_with_agreement(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.blocked')::uuid,'',current_setting('test.terms')::uuid);
select is((seller_privacy_preview(current_setting('test.tenant')::uuid,current_setting('test.blocked')::uuid)#>>'{blockers,bags}')::int,1,'unfinished custody blocks');
select set_config('test.blockedSession',create_reception_session(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.blocked')::uuid)::text,true);
select receive_garment(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.blockedSession')::uuid,'Synthetic receipt');
select is((seller_privacy_preview(current_setting('test.tenant')::uuid,current_setting('test.blocked')::uuid)#>>'{blockers,garments}')::int,1,'unprocessed garment prevents closure');
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000002621","role":"authenticated"}';
select throws_like($$select read_seller_review(repeat('e',64))$$,'%REVIEW_UNAVAILABLE%','old review link no longer exposes seller evidence');
select is(jsonb_array_length(my_seller_accounts()),1,'seller still has other store account only');
select throws_ok($$select seller_privacy_preview(current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid)$$,'42501',null,'seller cannot invoke staff privacy review');
reset role;
select ok(exists(select 1 from auth.users where id='f0000000-0000-4000-8000-000000002621'),'shared Auth identity preserved');
insert into tenant_members(tenant_id,user_id,role) values(current_setting('test.tenant')::uuid,'f0000000-0000-4000-8000-000000002622','staff');
set local role authenticated;
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000002622","role":"authenticated"}';
select throws_ok($$select seller_privacy_preview(current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid)$$,'42501',null,'staff cannot review erasure');
select throws_ok($$update sellers set name='Restored' where id=current_setting('test.seller')::uuid$$,'42501',null,'no direct writes');
select is((select count(*)::int from seller_privacy_events),0,'privacy decisions hidden from staff');
select set_config('komisio.communication_delivery','engine',true);
select throws_like($$select erase_seller_contact(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.blocked')::uuid,current_setting('test.blockedPreview')::jsonb->>'revision','Reviewed legal evidence',current_date+30,true)$$,'%FORBIDDEN%','session flags cannot authorize erasure');
reset role;
select throws_like($$update seller_privacy_events set retention_reason='Changed history'$$,'%IMMUTABLE_OPERATION%','privacy decisions remain immutable');
select throws_ok($$update settlement_statements set seller_contact='{}' where id=current_setting('test.statement')::uuid$$,'55000',null,'financial contact snapshot remains protected');
set local role anon;
select throws_ok($$select seller_privacy_preview(current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid)$$,'42501',null,'anonymous review denied');
select * from finish();
rollback;
